// Parse the text layer of House e-filed disclosure PDFs: Schedule A of annual
// reports (assets) and Periodic Transaction Reports (trades).
//
// The forms are generated by the House's e-filing system, so columns sit at
// fixed x positions given by each table's header row. Cells wrap onto
// following lines, and a value range ("$1,000,001 -" / "$5,000,000") is split
// across two of them.
import type { PdfText, Run } from "./pdf.js";

export type Owner = "self" | "spouse" | "joint" | "child";
const OWNERS: Record<string, Owner> = { SP: "spouse", JT: "joint", DC: "child" };

export interface Range {
  /** Lower bound in dollars; 0 for "None". */
  min: number;
  /** Upper bound; null when open-ended ("Over $50,000,000", "Spouse/DC Over $1,000,000"). */
  max: number | null;
  text: string;
  exact?: boolean;
}

export interface Holding {
  asset: string;
  /** House asset type code: ST stock, MF mutual fund, EF ETF, OP option, ... */
  type?: string;
  ticker?: string;
  owner: Owner;
  value?: Range;
  income?: string;
  location?: string;
  description?: string;
  comments?: string;
  subholdingOf?: string;
}

export interface Trade {
  asset: string;
  type?: string;
  ticker?: string;
  owner: Owner;
  /** P purchase, S sale, S (partial), E exchange. */
  transaction: string;
  subholdingOf?: string;
  date: string;
  notified: string;
  amount?: Range;
  description?: string;
  /** The filer's own note, e.g. that an adviser made the trade. */
  comments?: string;
  filingStatus?: string;
}

const DOLLARS = String.raw`\$[\d,]+(?:\.\d\d)?`;
const FULL_RANGE = new RegExp(
  String.raw`^(None|Undetermined|Unknown|${DOLLARS} - ${DOLLARS}|Over ${DOLLARS}|Spouse/DC Over ${DOLLARS}|${DOLLARS}|Less than ${DOLLARS})$`,
  "i"
);

export function parseRange(text: string | undefined): Range | undefined {
  if (!text) return undefined;
  const t = text.replace(/\s+/g, " ").trim();
  const nums = [...t.matchAll(/\$([\d,]+(?:\.\d+)?)/g)].map((m) => Number(m[1]!.replace(/,/g, "")));
  if (/^none$/i.test(t)) return { min: 0, max: 0, text: t };
  if (/over/i.test(t) && nums.length) return { min: nums[0]! + 1, max: null, text: t };
  if (nums.length === 2) return { min: nums[0]!, max: nums[1]!, text: t };
  // Filers may give an exact value instead of a category.
  if (nums.length === 1) return { min: nums[0]!, max: nums[0]!, text: t, exact: true };
  return { min: 0, max: null, text: t };
}

/** A label like "L\0\0\0\0\0\0\0: St. Helena" -> ["L", "St. Helena"]. The small-caps font has no text mapping. */
function label(s: string): [string, string] | undefined {
  const m = s.match(/^([A-Z])\u0000+(?: ([A-Z])\u0000*)?: ?(.*)$/s);
  return m ? [m[1]! + (m[2] ?? ""), m[3]!.trim()] : undefined;
}

const LABELS: Record<string, "location" | "description" | "filingStatus" | "subholdingOf" | "comments"> = {
  L: "location",
  D: "description",
  FS: "filingStatus",
  SO: "subholdingOf",
  C: "comments",
};

/** "Account ⇒ Fund ⇒ Stock (TKR) [ST]": the holding is the last part; the rest is the account it sits in. */
function assetBits(full: string) {
  const parts = full.split(/\s*⇒\s*/);
  const asset = parts.pop()!;
  const type = asset.match(/\[([A-Z0-9]{2})\]\s*$/)?.[1];
  // The closing parenthesis is sometimes missing: "(MSFT [OP]".
  const ticker = [...asset.matchAll(/\(([A-Z][A-Z.\-]{0,6})(?:\)|\s*\[)/g)].at(-1)?.[1];
  return { asset, type, ticker, ...(parts.length ? { subholdingOf: parts.join(" ⇒ ") } : {}) };
}

export function parseAnnualAssets(text: PdfText): Holding[] {
  const out: Holding[] = [];
  let cur: (Holding & { _value: string; _income: string }) | undefined;

  const flush = () => {
    if (!cur) return;
    cur.asset = cur.asset.replace(/\s+/g, " ").trim();
    Object.assign(cur, assetBits(cur.asset));
    cur.value = parseRange(cur._value);
    cur.income = cur._income.trim() || undefined;
    const { _value, _income, ...h } = cur;
    out.push(h);
    cur = undefined;
  };

  // Only Schedule A is assets; the section titles say which schedule we are in.
  let schedule = "";
  let table: { name: string; x: number }[] | undefined;
  for (const runs of text.runs) {
    const rows = new Map<number, Run[]>();
    for (const r of runs) rows.set(r.y, [...(rows.get(r.y) ?? []), r]);
    for (const row of rows.values()) {
      const first = row[0]!.s;
      const sec = first.match(/^S\u0000+ ([A-Z]): /);
      if (sec) {
        flush();
        schedule = sec[1]!;
        table = undefined;
        continue;
      }
      if (schedule !== "A") continue;
      if (row.some((r) => r.s === "Asset") && row.some((r) => r.s === "Owner")) {
        table = row.map((r) => ({ name: r.s.trim(), x: r.x }));
        continue;
      }
      if (!table || row.every((r) => /^(\$1,000\?|Tx\. >)$/.test(r.s))) continue;
      if (/^\* /.test(first)) {
        flush();
        continue;
      }
      const lab = label(first);
      if (lab && row.length === 1) {
        const key = LABELS[lab[0]];
        if (cur && key && key !== "filingStatus") {
          const prev = (cur as any)[key];
          (cur as any)[key] = prev ? `${prev} ${lab[1]}` : lab[1];
          (cur as any)._lastLabel = key;
        }
        continue;
      }
      const cells: Record<string, string> = {};
      for (const r of row) {
        const col = [...table].reverse().find((c) => r.x >= c.x - 4) ?? table[0]!;
        cells[col.name] = cells[col.name] ? `${cells[col.name]} ${r.s}` : r.s;
      }
      const asset = cells["Asset"];
      const value = cells["Value of Asset"];
      const valueDone = cur && FULL_RANGE.test(cur._value.trim());
      if (asset && value && (!cur || valueDone)) {
        flush();
        cur = {
          asset,
          owner: OWNERS[cells["Owner"] ?? ""] ?? "self",
          _value: value,
          _income: cells["Income"] ?? "",
        };
      } else if (cur) {
        // A label's text can wrap too ("D: ... worldwide to" / "institutional ...").
        if ((cur as any)._lastLabel && asset && !value && !cells["Owner"]) {
          const key = (cur as any)._lastLabel;
          (cur as any)[key] += ` ${asset}`;
          continue;
        }
        if (asset) cur.asset += ` ${asset}`;
        if (value) cur._value += ` ${value}`;
        if (cells["Income"]) cur._income += ` ${cells["Income"]}`;
      }
    }
  }
  flush();
  for (const h of out) delete (h as any)._lastLabel;
  return out;
}

export function parsePtr(text: PdfText): Trade[] {
  const out: Trade[] = [];
  let cur: (Trade & { _amount: string; _lastLabel?: string }) | undefined;
  let table: { name: string; x: number }[] | undefined;
  let headerY = 0;

  const flush = () => {
    if (!cur) return;
    cur.asset = cur.asset.replace(/\s+/g, " ").trim();
    Object.assign(cur, assetBits(cur.asset));
    cur.amount = parseRange(cur._amount);
    const { _amount, _lastLabel, ...t } = cur;
    out.push(t);
    cur = undefined;
  };

  for (const runs of text.runs) {
    const rows = new Map<number, Run[]>();
    for (const r of runs) rows.set(r.y, [...(rows.get(r.y) ?? []), r]);
    for (const [y, row] of rows) {
      const first = row[0]!.s;
      if (row.some((r) => r.s === "Asset") && row.some((r) => r.s === "Owner")) {
        table = row.map((r) => ({ name: r.s.trim(), x: r.x }));
        headerY = y;
        continue;
      }
      if (!table) continue;
      if (headerY - y < 30 && headerY > y && !row.some((r) => /\d\d\/\d\d\/\d{4}/.test(r.s))) continue;
      if (/^\* For the complete/.test(first) || /^I\u0000/.test(first)) {
        flush();
        table = undefined;
        continue;
      }
      const lab = label(first);
      if (lab && row.length === 1) {
        const key = LABELS[lab[0]];
        if (cur && key) {
          (cur as any)[key] = lab[1];
          cur._lastLabel = key;
        }
        continue;
      }
      const cells: Record<string, string> = {};
      for (const r of row) {
        const col = [...table].reverse().find((c) => r.x >= c.x - 4) ?? table[0]!;
        cells[col.name] = cells[col.name] ? `${cells[col.name]} ${r.s}` : r.s;
      }
      const date = cells["Date"];
      if (date && /\d\d\/\d\d\/\d{4}/.test(date)) {
        flush();
        cur = {
          asset: cells["Asset"] ?? "",
          owner: OWNERS[cells["Owner"] ?? ""] ?? "self",
          transaction: (cells["Transaction"] ?? "").trim(),
          date,
          notified: cells["Notification"] ?? "",
          _amount: cells["Amount"] ?? "",
        };
      } else if (cur) {
        if (cur._lastLabel && cells["Asset"] && Object.keys(cells).length === 1) {
          (cur as any)[cur._lastLabel] += ` ${cells["Asset"]}`;
          continue;
        }
        if (cells["Asset"]) cur.asset += ` ${cells["Asset"]}`;
        if (cells["Transaction"]) cur.transaction += ` ${cells["Transaction"]}`;
        if (cells["Amount"]) cur._amount += ` ${cells["Amount"]}`;
      }
    }
  }
  flush();
  return out;
}
